<template>
  <section class="coverflow" aria-label="环境音唱片轮播">
    <div class="meta" aria-live="polite">
      <p>O-MEETING · SOUND LIBRARY</p>
      <h2>{{ current.label }}</h2>
      <span>{{ status }}</span>
      <div class="rule" />
      <small>声景 {{ pad(activeIndex + 1) }} / {{ pad(items.length) }}</small>
    </div>
    <div class="stage" @pointerdown="emit('pointerdown', $event)" @pointermove="emit('pointermove', $event)" @pointerup="emit('pointerup')" @pointercancel="emit('pointerup')">
      <div class="track" />
      <button v-for="(item,index) in items" :key="item.type" class="record" :class="[`art-${item.type}`,{selected:index===activeIndex,playing:soundType===item.type}]" :style="recordStyle(index)" :aria-label="`播放${item.label}`" @click="emit('select',index)">
        <span class="art"><span class="rings"/><span class="label"><b>OM–0{{ index+1 }}</b><small>{{ item.label }}</small></span><i class="hole"/></span>
      </button>
    </div>
    <div class="controls"><span>{{ pad(activeIndex+1) }} <i>/</i> {{ pad(items.length) }}</span><button aria-label="上一个声景" @click="emit('step',-1)"><svg viewBox="0 0 24 24"><path d="M19 12H5m7 7-7-7 7-7"/></svg></button><button aria-label="下一个声景" @click="emit('step',1)"><svg viewBox="0 0 24 24"><path d="M5 12h14m-7-7 7 7-7 7"/></svg></button></div>
  </section>
</template>

<script setup lang="ts">
import { computed } from 'vue'
type Item={type:string;label:string;tint:string}
const props=defineProps<{items:Item[];activeIndex:number;soundType:string|null;status:string}>()
const emit=defineEmits<{select:[index:number];step:[direction:1|-1];pointerdown:[event:PointerEvent];pointermove:[event:PointerEvent];pointerup:[]}>()
const current=computed(()=>props.items[props.activeIndex])
const pad=(n:number)=>String(n).padStart(2,'0')
function recordStyle(index:number){let d=index-props.activeIndex;const n=props.items.length;if(d>n/2)d-=n;if(d< -n/2)d+=n;return {'--offset':d,'--depth':Math.abs(d),'--tint':props.items[index].tint} as Record<string,string|number>}
</script>

<style scoped>
