.record.selected .art{box-shadow:0 18px 44px #0008,0 0 0 2px rgba(58,210,181,.38),0 0 40px rgba(58,210,181,.2)}.art{position:absolute;inset:0;display:block;overflow:hidden;border-radius:50%;border:2px solid rgba(255,255,255,.22);background:radial-gradient(circle at 30% 22%,color-mix(in srgb,var(--tint),white 42%),var(--tint) 54%,color-mix(in srgb,var(--tint),black 48%));box-shadow:0 18px 44px #0008,inset 0 0 0 1px #ffffff2e}.art:before{content:"";position:absolute;inset:0;background:linear-gradient(135deg,#ffffff4a,transparent 39%,#0003 72%),repeating-radial-gradient(circle,transparent 0 5px,#0002 6px 7px)}.rings{position:absolute;inset:0;border-radius:50%;background:repeating-conic-gradient(from calc(var(--depth)*23deg),#ffffff18 0deg 4deg,transparent 5deg 23deg);opacity:.58}.art-white{background:radial-gradient(circle at 30% 22%,#eef1f4,#c3c9d2 54%,#6f7680)}.art-rain{background:linear-gradient(145deg,#34575d,#8ba9a2 52%,#263b44)}.art-waves{background:repeating-linear-gradient(155deg,#233d50 0 14px,#54748a 16px 34px,#283e50 38px 53px)}.art-fire{background:radial-gradient(circle at 55% 62%,#f2bd64,#a95131 48%,#3d2825)}.art-cafe{background:radial-gradient(circle at 50% 40%,#c6a77e,#75604b 52%,#332d27)}.label{position:absolute;z-index:2;left:50%;top:50%;width:27%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(circle,#f6f8fa 0 19%,#d5dae1 20% 23%,#eef0f4 24% 69%,#d2d7de 70% 73%,#f8fafc 74%);box-shadow:0 2px 9px #0005;color:#6b7280;font-size:clamp(6px,.7vw,9px);letter-spacing:.08em}.label b{font-weight:500}.label small{font-size:.65em;opacity:.72;margin-top:2px}.hole{position:absolute;z-index:3;left:50%;top:50%;width:8%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:#08090d;box-shadow:0 0 0 2px #dfe3e9}.playing .art{animation:spin 9s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.controls{position:absolute;z-index:20;right:28px;bottom:22px;display:flex;align-items:center;gap:8px;color:var(--text-2);font-size:11px;letter-spacing:.12em;font-variant-numeric:tabular-nums}.controls>span{margin-right:3px}.controls i{font-style:normal;color:var(--text-3);padding:0 4px}.controls button{width:38px;height:38px;display:grid;place-items:center;color:var(--text);border:1px solid var(--border-hover);background:rgba(8,9,13,.55);border-radius:50%;cursor:pointer;transition:background .2s,color .2s}.controls button:hover{background:rgba(255,255,255,.1)}.controls svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
@media(max-width:620px){.coverflow{height:290px}.meta{top:18px;left:18px;width:calc(100% - 36px)}.meta p{margin-bottom:9px}.meta h2{font-size:19px}.rule{display:none}.meta small{display:inline-block;margin-top:5px}.stage{top:70px}.track{top:73%}.record{left:44%;top:57%;--diameter:clamp(100px,30vw,145px);transform:translate(calc(var(--offset)*22vw - 50%),calc(var(--offset)*-10vw - 50%))}.record.selected{--diameter:clamp(175px,53vw,245px)}.controls{right:15px;bottom:12px;gap:6px}.controls button{width:36px;height:36px}}
@media(prefers-reduced-motion:reduce){.record,.controls button{transition:none}.playing .art{animation:none}}
</style>
